def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 20.0))

    guaranteed_units = int(supply // WATER_REQ)
    scarcity = guaranteed_units <= 1

    prev_bids = []
    threat_scores = []
    rich_alive = 0
    for agent_id, opp in alive:
        obudget = opp.get('budget', 0)
        ohp = opp.get('hp', 0)
        onw = opp.get('no_water_days', 0)
        if obudget >= 80:
            rich_alive += 1

        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        else:
            bid = 0.0

        score = float(bid)
        if ohp <= 3:
            score += 18.0
        elif ohp <= 5:
            score += 8.0
        if onw >= 1:
            score += 10.0
        if obudget < 40:
            score -= 8.0
        elif obudget > 140:
            score += 6.0
        threat_scores.append(score)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_threat = max(threat_scores) if threat_scores else 0.0

    emergency = hp <= 3 or no_water >= 1
    very_safe = hp >= 8 and no_water == 0

    if emergency:
        if scarcity:
            bid = max(95.0, highest_prev + 6.0, highest_threat + 2.0)
        else:
            bid = max(78.0, highest_prev + 3.0)
    else:
        if scarcity:
            if very_safe and rich_alive >= 2 and highest_prev >= 95.0:
                bid = 44.0
            else:
                bid = max(72.0, min(108.0, highest_prev + 2.5, highest_threat + 1.5))
        else:
            if very_safe:
                bid = max(28.0, min(62.0, highest_prev * 0.72 + 3.0))
            else:
                bid = max(48.0, min(82.0, highest_prev * 0.82 + 4.0))

    if day >= 8:
        bid += 6.0
    if hp <= 2:
        bid += 12.0
    if budget < 90:
        bid = min(bid, budget * 0.72)
    elif budget < 140:
        bid = min(bid, budget * 0.82)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Basic safety: if critically low hp, bid to secure water
    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        # No one to compete with
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday's immediate pressure from previous_trace
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass
            if prev.get('hp_after') is not None:
                try:
                    prev_hp_after.append(int(prev['hp_after']))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # If someone was already bidding aggressively yesterday, match just enough
    aggressive_threshold = DAILY_SALARY * 0.85  # 76.5

    # Supply-aware base: with supply in [15,25], water is scarce but not extreme.
    # Aim to win at a discount relative to highest_prev_bid.
    if highest_prev_bid >= aggressive_threshold:
        # If my hp is low or I've already missed water, increase bid
        if my_hp <= 2 or my_no_water_days >= 1:
            bid = min(my_budget, highest_prev_bid * 0.98)
        else:
            bid = min(my_budget, max(DAILY_SALARY * 0.45, highest_prev_bid * 0.92))
    else:
        # Lower pressure overall: undercut the top bidder slightly
        if my_hp <= 2 or my_no_water_days >= 2:
            bid = min(my_budget, DAILY_SALARY * 0.85)
        else:
            # Undercut expectation by targeting around 55% salary, but not below a floor
            bid = min(my_budget, max(DAILY_SALARY * 0.55, highest_prev_bid * 0.85))

    # Additional micro-adjustment: if Cindy survived with high hp yesterday, she likely bids consistently.
    # If her previous bid was known and high, nudge slightly lower to steal.
    for oid, o in alive_opps:
        if oid == 'Cindy':
            prev = o.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    c_bid = float(prev['bid'])
                    # If Cindy was bidding higher than my computed bid, try to sit just below it
                    if c_bid > 0:
                        bid = min(bid, max(0.0, c_bid - 2.0))
                except Exception:
                    pass

    # Ensure non-negative and keep within budget
    if bid < 0.0:
        bid = 0.0
    bid = min(float(bid), my_budget)

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if day_context['supply'] < WATER_REQ * 1.5:
        return min(my_status['budget'], max(avg_prev * 1.1, DAILY_SALARY * 0.8))

    return min(my_status['budget'], avg_prev * 0.95)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        # no trace data, use default based on HP
        if my_status['hp'] <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.95)
        elif my_status['hp'] <= 5:
            return min(my_status['budget'], DAILY_SALARY * 0.7)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.45)

    # Use median of yesterday's bids as baseline
    sorted_bids = sorted(yesterday_bids)
    mid = len(sorted_bids) // 2
    # integer index is safe because len is int
    if len(sorted_bids) % 2 == 1:
        median_bid = sorted_bids[mid]
    else:
        median_bid = (sorted_bids[mid-1] + sorted_bids[mid]) / 2.0

    max_yesterday = max(yesterday_bids)
    # Consider supply effect: if today's supply is low, aggression may increase
    supply = day_context['supply']
    supply_factor = 1.0
    if supply < 20:
        supply_factor = 1.3
    elif supply > 22:
        supply_factor = 0.85

    if my_status['hp'] <= 2:
        # desperate: bid up to 1.1 times max yesterday or salary
        target = max(DAILY_SALARY * 0.9, max_yesterday * 1.1)
    elif my_status['hp'] <= 5:
        # moderate need: try to beat median with a small premium
        target = min(median_bid * 1.15, DAILY_SALARY * 0.85)
    else:
        # healthy: conserve budget, undercut median
        target = min(median_bid * 0.85, DAILY_SALARY * 0.5)

    target = target * supply_factor
    # ensure we don't bid more than budget
    bid = min(my_status['budget'], target)
    # never bid negative
    bid = max(bid, 0.0)
    return bid
